<?php $page_title='Prescriptions';require_once __DIR__.'/../includes/header.php';$rows=$pdo->query("SELECT pr.*,p.name patient,d.name doctor FROM prescriptions pr JOIN patients p ON p.id=pr.patient_id JOIN doctors d ON d.id=pr.doctor_id ORDER BY pr.id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Prescriptions</h2><a href="add.php" class="btn btn-primary">+ Prescription</a></div><div class="card p-3"><table class="table"><thead><tr><th>Date</th><th>Patient</th><th>Doctor</th><th>Medicine</th><th>Dosage</th><th>Duration</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['prescription_date']?></td><td><?=e($r['patient'])?></td><td><?=e($r['doctor'])?></td><td><?=e($r['medicine'])?></td><td><?=e($r['dosage'])?></td><td><?=e($r['duration'])?></td></tr><?php endforeach;?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>